schema.default:
{
  "type": "object",
  "properties": {
    "code": {
      "type": "string",
      "description": "扇区编码"
    },
    "maxAltitude": {
      "type": "number",
      "description": "最高高度（米）"
    },
    "minAltitude": {
      "type": "number",
      "description": "最低高度（米）"
    },
    "name": {
      "type": "string",
      "description": "扇区名称"
    },
    "shape": {
      "type": "integer",
      "title": "形状",
      "enum": [
        1,
        2,
        4
      ]
    },
    "shapeCircle": {
      "type": "object",
      "properties": {
        "lat": {
          "type": "number",
          "title": "圆心纬度"
        },
        "lon": {
          "type": "number",
          "title": "圆心经度"
        },
        "radiusMeters": {
          "type": "number",
          "title": "半径"
        }
      },
      "title": "圆形绘图",
      "required": [
        "lat",
        "lon",
        "radiusMeters"
      ]
    },
    "shapeLineBuffer": {
      "type": "object",
      "properties": {
        "distanceMeters": {
          "type": "number",
          "title": "线宽度"
        },
        "geoLine": {
          "type": "object",
          "properties": {
            "coordinates": {
              "type": "array",
              "items": {
                "type": "array",
                "items": {
                  "type": "number"
                }
              },
              "title": "线段点坐标",
              "description": "二维数组"
            }
          },
          "title": "线段",
          "required": [
            "coordinates"
          ]
        }
      },
      "title": "线缓冲区绘图",
      "required": [
        "distanceMeters",
        "geoLine"
      ]
    },
    "polygon": {
      "type": "object",
      "properties": {
        "coordinates": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": "array",
              "items": {
                "type": "number",
                "format": "double"
              }
            }
          }
        },
        "type": {
          "type": "string"
        }
      },
      "title": "区域(描边)",
      "$$ref": "#/definitions/Polygon"
    },
    "sectorType": {
      "type": "string",
      "description": "枚举",
      "enum": [
        "0",
        "1"
      ],
      "title": "扇区类型"
    },
    "dataSource": {
      "type": "string",
      "title": "数据来源",
      "enum": [
        "0",
        "1"
      ],
      "description": "枚举"
    },
    "direction": {
      "type": "string",
      "title": "进出方向",
      "description": "枚举",
      "enum": [
        "0",
        "1",
        "2"
      ]
    }
  },
  "required": [
    "shape",
    "dataSource",
    "direction"
  ]
}
